28: #include "libImaging/Imaging.h"
29: 
30: /* -------------------------------------------------------------------- */
31: /* Windows DIB support */
32: 
33: #ifdef _WIN32
34: 
35: #include "libImaging/ImDib.h"
36: 
37: #if SIZEOF_VOID_P == 8
38: #define F_HANDLE "K"
39: #else
40: #define F_HANDLE "k"
41: #endif
42: 
43: typedef struct {
44:     PyObject_HEAD ImagingDIB dib;
45: } ImagingDisplayObject;
46: 
47: static PyTypeObject ImagingDisplayType;
48: 
49: static ImagingDisplayObject *
50: _new(const ModeID mode, int xsize, int ysize) {
51:     ImagingDisplayObject *display;
52: 
53:     if (PyType_Ready(&ImagingDisplayType) < 0) {
54:         return NULL;
55:     }
56: 
57:     display = PyObject_New(ImagingDisplayObject, &ImagingDisplayType);
58:     if (display == NULL) {
59:         return NULL;
60:     }
61: 
62:     display->dib = ImagingNewDIB(mode, xsize, ysize);
63:     if (!display->dib) {
64:         Py_DECREF(display);
65:         return NULL;
66:     }
67: 
68:     return display;
69: }
70: 
71: static void
72: _delete(ImagingDisplayObject *display) {
73:     if (display->dib) {
74:         ImagingDeleteDIB(display->dib);
75:     }
76:     PyObject_Del(display);
77: }
78: 
79: static PyObject *
80: _expose(ImagingDisplayObject *display, PyObject *args) {
81:     HDC hdc;
82:     if (!PyArg_ParseTuple(args, F_HANDLE, &hdc)) {
83:         return NULL;
84:     }
85: 
86:     ImagingExposeDIB(display->dib, hdc);
87: 
88:     Py_RETURN_NONE;
89: }
90: 
91: static PyObject *
92: _draw(ImagingDisplayObject *display, PyObject *args) {
93:     HDC hdc;
94:     int dst[4];
95:     int src[4];
96:     if (!PyArg_ParseTuple(
97:             args,
98:             F_HANDLE "(iiii)(iiii)",
99:             &hdc,
100:             dst + 0,
101:             dst + 1,
102:             dst + 2,
103:             dst + 3,
104:             src + 0,
105:             src + 1,
106:             src + 2,
107:             src + 3
108:         )) {
109:         return NULL;
110:     }
111: 
112:     ImagingDrawDIB(display->dib, hdc, dst, src);
113: 
114:     Py_RETURN_NONE;
115: }
116: 
117: extern Imaging
118: PyImaging_AsImaging(PyObject *op);
119: 
120: static PyObject *
121: _paste(ImagingDisplayObject *display, PyObject *args) {
122:     Imaging im;
123: 
124:     PyObject *op;
125:     int xy[4];
126:     xy[0] = xy[1] = xy[2] = xy[3] = 0;
127:     if (!PyArg_ParseTuple(args, "O|(iiii)", &op, xy + 0, xy + 1, xy + 2, xy + 3)) {
128:         return NULL;
129:     }
130:     im = PyImaging_AsImaging(op);
131:     if (!im) {
132:         return NULL;
133:     }
134: 
135:     if (xy[2] <= xy[0]) {
136:         xy[2] = xy[0] + im->xsize;
137:     }
138:     if (xy[3] <= xy[1]) {
139:         xy[3] = xy[1] + im->ysize;
140:     }
141: 
142:     ImagingPasteDIB(display->dib, im, xy);
143: 
144:     Py_RETURN_NONE;
145: }
146: 
147: static PyObject *
148: _query_palette(ImagingDisplayObject *display, PyObject *args) {
149:     HDC hdc;
150:     int status;
151: 
152:     if (!PyArg_ParseTuple(args, F_HANDLE, &hdc)) {
153:         return NULL;
154:     }
155: 
156:     status = ImagingQueryPaletteDIB(display->dib, hdc);
157: 
158:     return Py_BuildValue("i", status);
159: }
160: 
161: static PyObject *
162: _getdc(ImagingDisplayObject *display, PyObject *args) {
163:     HWND window;
164:     HDC dc;
165: 
166:     if (!PyArg_ParseTuple(args, F_HANDLE, &window)) {
167:         return NULL;
168:     }
169: 
170:     dc = GetDC(window);
171:     if (!dc) {
172:         PyErr_SetString(PyExc_OSError, "cannot create dc");
173:         return NULL;
174:     }
175: 
176:     return Py_BuildValue(F_HANDLE, dc);
177: }
178: 
179: static PyObject *
180: _releasedc(ImagingDisplayObject *display, PyObject *args) {
181:     HWND window;
182:     HDC dc;
183: 
184:     if (!PyArg_ParseTuple(args, F_HANDLE F_HANDLE, &window, &dc)) {
185:         return NULL;
186:     }
187: 
188:     ReleaseDC(window, dc);
189: 
190:     Py_RETURN_NONE;
191: }
192: 
193: static PyObject *
194: _frombytes(ImagingDisplayObject *display, PyObject *args) {
195:     Py_buffer buffer;
196: 
197:     if (!PyArg_ParseTuple(args, "y*:frombytes", &buffer)) {
198:         return NULL;
199:     }
200: 
201:     if (display->dib->ysize * display->dib->linesize != buffer.len) {
202:         PyBuffer_Release(&buffer);
203:         PyErr_SetString(PyExc_ValueError, "wrong size");
204:         return NULL;
205:     }
206: 
207:     memcpy(display->dib->bits, buffer.buf, buffer.len);
208: 
209:     PyBuffer_Release(&buffer);
210:     Py_RETURN_NONE;
211: }
212: 
213: static PyObject *
214: _tobytes(ImagingDisplayObject *display, PyObject *args) {
215:     if (!PyArg_ParseTuple(args, ":tobytes")) {
216:         return NULL;
217:     }
218: 
219:     return PyBytes_FromStringAndSize(
220:         display->dib->bits, display->dib->ysize * display->dib->linesize
221:     );
222: }
