225:     {"draw", (PyCFunction)_draw, METH_VARARGS},
226:     {"expose", (PyCFunction)_expose, METH_VARARGS},
227:     {"paste", (PyCFunction)_paste, METH_VARARGS},
228:     {"query_palette", (PyCFunction)_query_palette, METH_VARARGS},
229:     {"getdc", (PyCFunction)_getdc, METH_VARARGS},
230:     {"releasedc", (PyCFunction)_releasedc, METH_VARARGS},
231:     {"frombytes", (PyCFunction)_frombytes, METH_VARARGS},
232:     {"tobytes", (PyCFunction)_tobytes, METH_VARARGS},
233:     {NULL, NULL} /* sentinel */
