285: /* Windows screen grabber */
286: 
287: typedef HANDLE(__stdcall *Func_GetWindowDpiAwarenessContext)(HANDLE);
288: typedef HANDLE(__stdcall *Func_SetThreadDpiAwarenessContext)(HANDLE);
289: 
290: PyObject *
291: PyImaging_GrabScreenWin32(PyObject *self, PyObject *args) {
292:     int x = 0, y = 0, width = -1, height;
293:     int includeLayeredWindows = 0, screens = 0;
294:     HBITMAP bitmap;
295:     BITMAPCOREHEADER core;
296:     HDC screen, screen_copy;
297:     HWND wnd;
298:     DWORD rop;
299:     PyObject *buffer;
300:     HANDLE dpiAwareness = NULL;
301:     HMODULE user32;
302:     Func_GetWindowDpiAwarenessContext GetWindowDpiAwarenessContext_function;
303:     Func_SetThreadDpiAwarenessContext SetThreadDpiAwarenessContext_function;
304: 
305:     if (!PyArg_ParseTuple(
306:             args, "|ii" F_HANDLE, &includeLayeredWindows, &screens, &wnd
307:         )) {
308:         return NULL;
309:     }
310: 
311:     /* step 1: create a memory DC large enough to hold the
312:        entire screen */
313: 
314:     if (screens == -1) {
315:         screen = GetDC(wnd);
316:         if (screen == NULL) {
317:             PyErr_SetString(PyExc_OSError, "unable to get device context for handle");
318:             return NULL;
319:         }
320:     } else {
321:         screen = CreateDC("DISPLAY", NULL, NULL, NULL);
322:     }
323:     screen_copy = CreateCompatibleDC(screen);
324: 
325:     // added in Windows 10 (1607)
326:     // loaded dynamically to avoid link errors
327:     user32 = LoadLibraryA("User32.dll");
328:     SetThreadDpiAwarenessContext_function = (Func_SetThreadDpiAwarenessContext)
329:         GetProcAddress(user32, "SetThreadDpiAwarenessContext");
330:     if (SetThreadDpiAwarenessContext_function != NULL) {
331:         GetWindowDpiAwarenessContext_function = (Func_GetWindowDpiAwarenessContext)
332:             GetProcAddress(user32, "GetWindowDpiAwarenessContext");
333:         if (screens == -1 && GetWindowDpiAwarenessContext_function != NULL) {
334:             dpiAwareness = GetWindowDpiAwarenessContext_function(wnd);
335:         }
336:         // DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE = ((DPI_CONTEXT_HANDLE)-3)
337:         dpiAwareness = SetThreadDpiAwarenessContext_function(
338:             dpiAwareness == NULL ? (HANDLE)-3 : dpiAwareness
339:         );
340:     }
341: 
342:     if (screens == 1) {
343:         x = GetSystemMetrics(SM_XVIRTUALSCREEN);
344:         y = GetSystemMetrics(SM_YVIRTUALSCREEN);
345:         width = GetSystemMetrics(SM_CXVIRTUALSCREEN);
346:         height = GetSystemMetrics(SM_CYVIRTUALSCREEN);
347:     } else if (screens == -1) {
348:         RECT rect;
349:         if (GetClientRect(wnd, &rect)) {
350:             width = rect.right;
351:             height = rect.bottom;
352:         }
353:     } else {
354:         width = GetDeviceCaps(screen, HORZRES);
355:         height = GetDeviceCaps(screen, VERTRES);
356:     }
357: 
358:     if (SetThreadDpiAwarenessContext_function != NULL) {
359:         SetThreadDpiAwarenessContext_function(dpiAwareness);
360:     }
361: 
362:     FreeLibrary(user32);
363: 
364:     if (width == -1) {
365:         goto error;
366:     }
367: 
368:     bitmap = CreateCompatibleBitmap(screen, width, height);
369:     if (!bitmap) {
370:         goto error;
371:     }
372: 
373:     if (!SelectObject(screen_copy, bitmap)) {
374:         goto error;
375:     }
376: 
377:     /* step 2: copy bits into memory DC bitmap */
378: 
379:     rop = SRCCOPY;
380:     if (includeLayeredWindows) {
381:         rop |= CAPTUREBLT;
382:     }
383:     if (!BitBlt(screen_copy, 0, 0, width, height, screen, x, y, rop)) {
384:         goto error;
385:     }
386: 
387:     /* step 3: extract bits from bitmap */
388: 
389:     buffer = PyBytes_FromStringAndSize(NULL, height * ((width * 3 + 3) & -4));
390:     if (!buffer) {
391:         return NULL;
392:     }
393: 
394:     core.bcSize = sizeof(core);
395:     core.bcWidth = width;
396:     core.bcHeight = height;
397:     core.bcPlanes = 1;
398:     core.bcBitCount = 24;
399:     if (!GetDIBits(
400:             screen_copy,
401:             bitmap,
402:             0,
403:             height,
404:             PyBytes_AS_STRING(buffer),
405:             (BITMAPINFO *)&core,
406:             DIB_RGB_COLORS
407:         )) {
408:         goto error;
409:     }
410: 
411:     DeleteObject(bitmap);
412:     DeleteDC(screen_copy);
413:     if (screens == -1) {
414:         ReleaseDC(wnd, screen);
415:     } else {
416:         DeleteDC(screen);
417:     }
418: 
419:     return Py_BuildValue("(ii)(ii)N", x, y, width, height, buffer);
420: 
421: error:
422:     PyErr_SetString(PyExc_OSError, "screen grab failed");
423: 
424:     DeleteDC(screen_copy);
425:     if (screens == -1) {
426:         ReleaseDC(wnd, screen);
427:     } else {
428:         DeleteDC(screen);
429:     }
430: 
431:     return NULL;
432: }
