435: /* Windows clipboard grabber */
436: 
437: PyObject *
438: PyImaging_GrabClipboardWin32(PyObject *self, PyObject *args) {
439:     HANDLE handle = NULL;
440:     int size;
441:     void *data;
442:     PyObject *result;
443:     UINT format;
444:     UINT formats[] = {CF_DIB, CF_DIBV5, CF_HDROP, RegisterClipboardFormatA("PNG"), 0};
445:     LPCSTR format_names[] = {"DIB", "DIB", "file", "png", NULL};
446: 
447:     if (!OpenClipboard(NULL)) {
448:         // Maybe the clipboard is temporarily in use by another process.
449:         // Wait and try again
450:         Sleep(500);
451: 
452:         if (!OpenClipboard(NULL)) {
453:             PyErr_SetString(PyExc_OSError, "failed to open clipboard");
454:             return NULL;
455:         }
456:     }
457: 
458:     // find best format as set by clipboard owner
459:     format = 0;
460:     while (!handle && (format = EnumClipboardFormats(format))) {
461:         for (UINT i = 0; formats[i] != 0; i++) {
462:             if (format == formats[i]) {
463:                 handle = GetClipboardData(format);
464:                 format = i;
465:                 break;
466:             }
467:         }
468:     }
469: 
470:     if (!handle) {
471:         CloseClipboard();
472:         return Py_BuildValue("zO", NULL, Py_None);
473:     }
474: 
475:     data = GlobalLock(handle);
476:     size = GlobalSize(handle);
477: 
478:     result = PyBytes_FromStringAndSize(data, size);
479: 
480:     GlobalUnlock(handle);
481:     CloseClipboard();
482: 
483:     if (!result) {
484:         return NULL;
485:     }
486:     return Py_BuildValue("zN", format_names[format], result);
487: }
