514: static LRESULT CALLBACK
515: windowCallback(HWND wnd, UINT message, WPARAM wParam, LPARAM lParam) {
516:     PAINTSTRUCT ps;
517:     PyObject *callback = NULL;
518:     PyObject *result;
519:     PyThreadState *threadstate;
520:     PyThreadState *current_threadstate;
521:     HDC dc;
522:     RECT rect;
523:     LRESULT status = 0;
524: 
525:     /* set up threadstate for messages that calls back into python */
526:     switch (message) {
527:         case WM_CREATE:
528:             mainloop++;
529:             break;
530:         case WM_DESTROY:
531:             mainloop--;
532:             /* fall through... */
533:         case WM_PAINT:
534:         case WM_SIZE:
535:             callback = (PyObject *)GetWindowLongPtr(wnd, 0);
536:             if (callback) {
537:                 threadstate =
538:                     (PyThreadState *)GetWindowLongPtr(wnd, sizeof(PyObject *));
539:                 current_threadstate = PyThreadState_Swap(NULL);
540:                 PyEval_RestoreThread(threadstate);
541:             } else {
542:                 return DefWindowProc(wnd, message, wParam, lParam);
543:             }
544:     }
545: 
546:     /* process message */
547:     switch (message) {
548:         case WM_PAINT:
549:             /* redraw (part of) window.  this generates a WCK-style
550:                damage/clear/repair cascade */
551:             BeginPaint(wnd, &ps);
552:             dc = GetDC(wnd);
553:             GetWindowRect(wnd, &rect); /* in screen coordinates */
554: 
555:             result = PyObject_CallFunction(
556:                 callback,
557:                 "siiii",
558:                 "damage",
559:                 ps.rcPaint.left,
560:                 ps.rcPaint.top,
561:                 ps.rcPaint.right,
562:                 ps.rcPaint.bottom
563:             );
564:             if (result) {
565:                 Py_DECREF(result);
566:             } else {
567:                 callback_error("window damage callback");
568:             }
569: 
570:             result = PyObject_CallFunction(
571:                 callback,
572:                 "s" F_HANDLE "iiii",
573:                 "clear",
574:                 dc,
575:                 0,
576:                 0,
577:                 rect.right - rect.left,
578:                 rect.bottom - rect.top
579:             );
580:             if (result) {
581:                 Py_DECREF(result);
582:             } else {
583:                 callback_error("window clear callback");
584:             }
585: 
586:             result = PyObject_CallFunction(
587:                 callback,
588:                 "s" F_HANDLE "iiii",
589:                 "repair",
590:                 dc,
591:                 0,
592:                 0,
593:                 rect.right - rect.left,
594:                 rect.bottom - rect.top
595:             );
596:             if (result) {
597:                 Py_DECREF(result);
598:             } else {
599:                 callback_error("window repair callback");
600:             }
601: 
602:             ReleaseDC(wnd, dc);
603:             EndPaint(wnd, &ps);
604:             break;
605: 
606:         case WM_SIZE:
607:             /* resize window */
608:             result = PyObject_CallFunction(
609:                 callback, "sii", "resize", LOWORD(lParam), HIWORD(lParam)
610:             );
611:             if (result) {
612:                 InvalidateRect(wnd, NULL, 1);
613:                 Py_DECREF(result);
614:             } else {
615:                 callback_error("window resize callback");
616:             }
617:             break;
618: 
619:         case WM_DESTROY:
620:             /* destroy window */
621:             result = PyObject_CallFunction(callback, "s", "destroy");
622:             if (result) {
623:                 Py_DECREF(result);
624:             } else {
625:                 callback_error("window destroy callback");
626:             }
627:             Py_DECREF(callback);
628:             break;
629: 
630:         default:
631:             status = DefWindowProc(wnd, message, wParam, lParam);
632:     }
633: 
634:     if (callback) {
635:         /* restore thread state */
636:         PyEval_SaveThread();
637:         PyThreadState_Swap(current_threadstate);
638:     }
639: 
640:     return status;
641: }
