737: PyObject *
738: PyImaging_DrawWmf(PyObject *self, PyObject *args) {
739:     HBITMAP bitmap;
740:     HENHMETAFILE meta;
741:     BITMAPCOREHEADER core;
742:     HDC dc;
743:     RECT rect;
744:     PyObject *buffer = NULL;
745:     void *ptr;
746: 
747:     char *data;
748:     Py_ssize_t datasize;
749:     int width, height;
750:     int x0, y0, x1, y1;
751:     if (!PyArg_ParseTuple(
752:             args,
753:             "y#(ii)(iiii):_load",
754:             &data,
755:             &datasize,
756:             &width,
757:             &height,
758:             &x0,
759:             &x1,
760:             &y0,
761:             &y1
762:         )) {
763:         return NULL;
764:     }
765: 
766:     /* step 1: copy metafile contents into METAFILE object */
767: 
768:     if (datasize > 22 && GET32(data, 0) == 0x9ac6cdd7) {
769:         /* placeable windows metafile (22-byte aldus header) */
770:         meta = SetWinMetaFileBits(datasize - 22, data + 22, NULL, NULL);
771: 
772:     } else if (datasize > 80 && GET32(data, 0) == 1 && GET32(data, 40) == 0x464d4520) {
773:         /* enhanced metafile */
774:         meta = SetEnhMetaFileBits(datasize, data);
775: 
776:     } else {
777:         /* unknown meta format */
778:         meta = NULL;
779:     }
780: 
781:     if (!meta) {
782:         PyErr_SetString(PyExc_OSError, "cannot load metafile");
783:         return NULL;
784:     }
785: 
786:     /* step 2: create bitmap */
787: 
788:     core.bcSize = sizeof(core);
789:     core.bcWidth = width;
790:     core.bcHeight = height;
791:     core.bcPlanes = 1;
792:     core.bcBitCount = 24;
793: 
794:     dc = CreateCompatibleDC(NULL);
795: 
796:     bitmap = CreateDIBSection(dc, (BITMAPINFO *)&core, DIB_RGB_COLORS, &ptr, NULL, 0);
797: 
798:     if (!bitmap) {
799:         PyErr_SetString(PyExc_OSError, "cannot create bitmap");
800:         goto error;
801:     }
802: 
803:     if (!SelectObject(dc, bitmap)) {
804:         PyErr_SetString(PyExc_OSError, "cannot select bitmap");
805:         goto error;
806:     }
807: 
808:     /* step 3: render metafile into bitmap */
809: 
810:     rect.left = rect.top = 0;
811:     rect.right = width;
812:     rect.bottom = height;
813: 
814:     /* FIXME: make background transparent? configurable? */
815:     FillRect(dc, &rect, GetStockObject(WHITE_BRUSH));
816: 
817:     EnumEnhMetaFile(dc, meta, enhMetaFileProc, NULL, &rect);
818: 
819:     /* step 4: extract bits from bitmap */
820: 
821:     GdiFlush();
822: 
823:     buffer = PyBytes_FromStringAndSize(ptr, height * ((width * 3 + 3) & -4));
824: 
825: error:
826:     DeleteEnhMetaFile(meta);
827: 
828:     if (bitmap) {
829:         DeleteObject(bitmap);
830:     }
831: 
832:     DeleteDC(dc);
833: 
834:     return buffer;
835: }
