848: PyObject *
849: PyImaging_GrabScreenX11(PyObject *self, PyObject *args) {
850:     int width, height;
851:     char *display_name;
852:     xcb_connection_t *connection;
853:     int screen_number;
854:     xcb_screen_iterator_t iter;
855:     xcb_screen_t *screen = NULL;
856:     xcb_get_image_reply_t *reply;
857:     xcb_generic_error_t *error;
858:     PyObject *buffer = NULL;
859: 
860:     if (!PyArg_ParseTuple(args, "|z", &display_name)) {
861:         return NULL;
862:     }
863: 
864:     /* connect to X and get screen data */
865: 
866:     connection = xcb_connect(display_name, &screen_number);
867:     if (xcb_connection_has_error(connection)) {
868:         PyErr_Format(
869:             PyExc_OSError,
870:             "X connection failed: error %i",
871:             xcb_connection_has_error(connection)
872:         );
873:         xcb_disconnect(connection);
874:         return NULL;
875:     }
876: 
877:     iter = xcb_setup_roots_iterator(xcb_get_setup(connection));
878:     for (; iter.rem; --screen_number, xcb_screen_next(&iter)) {
879:         if (screen_number == 0) {
880:             screen = iter.data;
881:             break;
882:         }
883:     }
884:     if (screen == NULL || screen->root == 0) {
885:         // this case is usually caught with "X connection failed: error 6" above
886:         xcb_disconnect(connection);
887:         PyErr_SetString(PyExc_OSError, "X screen not found");
888:         return NULL;
889:     }
890: 
891:     width = screen->width_in_pixels;
892:     height = screen->height_in_pixels;
893: 
894:     /* get image data */
895: 
896:     reply = xcb_get_image_reply(
897:         connection,
898:         xcb_get_image(
899:             connection,
900:             XCB_IMAGE_FORMAT_Z_PIXMAP,
901:             screen->root,
902:             0,
903:             0,
904:             width,
905:             height,
906:             0x00ffffff
907:         ),
908:         &error
909:     );
910:     if (reply == NULL) {
911:         PyErr_Format(
912:             PyExc_OSError,
913:             "X get_image failed: error %i (%i, %i, %i)",
914:             error->error_code,
915:             error->major_code,
916:             error->minor_code,
917:             error->resource_id
918:         );
919:         free(error);
920:         xcb_disconnect(connection);
921:         return NULL;
922:     }
923: 
924:     /* store data in Python buffer */
925: 
926:     if (reply->depth == 24) {
927:         buffer = PyBytes_FromStringAndSize(
928:             (char *)xcb_get_image_data(reply), xcb_get_image_data_length(reply)
929:         );
930:     } else {
931:         PyErr_Format(PyExc_OSError, "unsupported bit depth: %i", reply->depth);
932:     }
933: 
934:     free(reply);
935:     xcb_disconnect(connection);
936: 
937:     if (!buffer) {
938:         return NULL;
939:     }
940: 
941:     return Py_BuildValue("(ii)N", width, height, buffer);
942: }
943: 
944: #endif /* HAVE_XCB */

