22: #include "Imaging.h"
23: 
24: #ifdef _WIN32
25: 
26: #include "ImDib.h"
27: 
28: ModeID
29: ImagingGetModeDIB(int size_out[2]) {
30:     /* Get device characteristics */
31: 
32:     const HDC dc = CreateCompatibleDC(NULL);
33: 
34:     ModeID mode = IMAGING_MODE_P;
35:     if (!(GetDeviceCaps(dc, RASTERCAPS) & RC_PALETTE)) {
36:         mode = IMAGING_MODE_RGB;
37:         if (GetDeviceCaps(dc, BITSPIXEL) == 1) {
38:             mode = IMAGING_MODE_1;
39:         }
40:     }
41: 
42:     if (size_out) {
43:         size_out[0] = GetDeviceCaps(dc, HORZRES);
44:         size_out[1] = GetDeviceCaps(dc, VERTRES);
45:     }
46: 
47:     DeleteDC(dc);
48: 
49:     return mode;
50: }
51: 
52: ImagingDIB
53: ImagingNewDIB(const ModeID mode, int xsize, int ysize) {
54:     /* Create a Windows bitmap */
55: 
56:     ImagingDIB dib;
57:     RGBQUAD *palette;
58:     int i;
59: 
60:     /* Check mode */
61:     if (mode != IMAGING_MODE_1 && mode != IMAGING_MODE_L && mode != IMAGING_MODE_RGB) {
62:         return (ImagingDIB)ImagingError_ModeError();
63:     }
64: 
65:     const int pixelsize = mode == IMAGING_MODE_RGB ? 3 : 1;
66: 
67:     /* Create DIB context and info header */
68:     /* malloc check ok, small constant allocation */
69:     dib = (ImagingDIB)malloc(sizeof(*dib));
70:     if (!dib) {
71:         return (ImagingDIB)ImagingError_MemoryError();
72:     }
73:     /* malloc check ok, small constant allocation */
74:     dib->info = (BITMAPINFO *)malloc(sizeof(BITMAPINFOHEADER) + 256 * sizeof(RGBQUAD));
75:     if (!dib->info) {
76:         free(dib);
77:         return (ImagingDIB)ImagingError_MemoryError();
78:     }
79: 
80:     memset(dib->info, 0, sizeof(BITMAPINFOHEADER));
81:     dib->info->bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
82:     dib->info->bmiHeader.biWidth = xsize;
83:     dib->info->bmiHeader.biHeight = ysize;
84:     dib->info->bmiHeader.biPlanes = 1;
85:     dib->info->bmiHeader.biBitCount = pixelsize * 8;
86:     dib->info->bmiHeader.biCompression = BI_RGB;
87: 
88:     /* Create DIB */
89:     dib->dc = CreateCompatibleDC(NULL);
90:     if (!dib->dc) {
91:         free(dib->info);
92:         free(dib);
93:         return (ImagingDIB)ImagingError_MemoryError();
94:     }
95: 
96:     dib->bitmap = CreateDIBSection(
97:         dib->dc, dib->info, DIB_RGB_COLORS, (void **)&dib->bits, NULL, 0
98:     );
99:     if (!dib->bitmap) {
100:         free(dib->info);
101:         free(dib);
102:         return (ImagingDIB)ImagingError_MemoryError();
103:     }
104: 
105:     dib->mode = mode;
106:     dib->xsize = xsize;
107:     dib->ysize = ysize;
108: 
109:     dib->pixelsize = pixelsize;
110:     dib->linesize = (xsize * pixelsize + 3) & -4;
111: 
112:     if (dib->pixelsize == 1) {
113:         dib->pack = dib->unpack = (ImagingShuffler)memcpy;
114:     } else {
115:         dib->pack = ImagingPackBGR;
116:         dib->unpack = ImagingPackBGR;
117:     }
118: 
119:     /* Bind the DIB to the device context */
120:     dib->old_bitmap = SelectObject(dib->dc, dib->bitmap);
121: 
122:     palette = dib->info->bmiColors;
123: 
124:     /* Bind a palette to it as well (only required for 8-bit DIBs) */
125:     if (dib->pixelsize == 1) {
126:         for (i = 0; i < 256; i++) {
127:             palette[i].rgbRed = palette[i].rgbGreen = palette[i].rgbBlue = i;
128:             palette[i].rgbReserved = 0;
129:         }
130:         SetDIBColorTable(dib->dc, 0, 256, palette);
131:     }
132: 
133:     /* Create an associated palette (for 8-bit displays only) */
134:     if (ImagingGetModeDIB(NULL) == IMAGING_MODE_P) {
135:         char palbuf[sizeof(LOGPALETTE) + 256 * sizeof(PALETTEENTRY)];
136:         LPLOGPALETTE pal = (LPLOGPALETTE)palbuf;
137:         int i, r, g, b;
138: 
139:         /* Load system palette */
140:         pal->palVersion = 0x300;
141:         pal->palNumEntries = 256;
142:         GetSystemPaletteEntries(dib->dc, 0, 256, pal->palPalEntry);
143: 
144:         if (mode == IMAGING_MODE_L) {
145:             /* Grayscale DIB.  Fill all 236 slots with a grayscale ramp
146:              * (this is usually overkill on Windows since VGA only offers
147:              * 6 bits grayscale resolution).  Ignore the slots already
148:              * allocated by Windows */
149: 
150:             i = 10;
151:             for (r = 0; r < 236; r++) {
152:                 pal->palPalEntry[i].peRed = pal->palPalEntry[i].peGreen =
153:                     pal->palPalEntry[i].peBlue = i;
154:                 i++;
155:             }
156: 
157:             dib->palette = CreatePalette(pal);
158:         } else if (mode == IMAGING_MODE_RGB) {
159: #ifdef CUBE216
160: 
161:             /* Colour DIB.  Create a 6x6x6 colour cube (216 entries) and
162:              * add 20 extra graylevels for best result with grayscale
163:              * images. */
164: 
165:             i = 10;
166:             for (r = 0; r < 256; r += 51) {
167:                 for (g = 0; g < 256; g += 51) {
168:                     for (b = 0; b < 256; b += 51) {
169:                         pal->palPalEntry[i].peRed = r;
170:                         pal->palPalEntry[i].peGreen = g;
171:                         pal->palPalEntry[i].peBlue = b;
172:                         i++;
173:                     }
174:                 }
175:             }
176:             for (r = 1; r < 22 - 1; r++) {
177:                 /* Black and white are already provided by the cube. */
178:                 pal->palPalEntry[i].peRed = pal->palPalEntry[i].peGreen =
179:                     pal->palPalEntry[i].peBlue = r * 255 / (22 - 1);
180:                 i++;
181:             }
182: 
183: #else
184: 
185:             /* Colour DIB.  Alternate palette. */
186: 
187:             i = 10;
188:             for (r = 0; r < 256; r += 37) {
189:                 for (g = 0; g < 256; g += 32) {
190:                     for (b = 0; b < 256; b += 64) {
191:                         pal->palPalEntry[i].peRed = r;
192:                         pal->palPalEntry[i].peGreen = g;
193:                         pal->palPalEntry[i].peBlue = b;
194:                         i++;
195:                     }
196:                 }
197:             }
198: 
199: #endif
200: 
201:             dib->palette = CreatePalette(pal);
202:         }
203:     }
204: 
205:     return dib;
206: }
207: 
208: void
209: ImagingPasteDIB(ImagingDIB dib, Imaging im, int xy[4]) {
210:     /* Paste image data into a bitmap */
211: 
212:     /* FIXME: check size! */
213: 
214:     int y;
215:     for (y = 0; y < im->ysize; y++) {
216:         dib->pack(
217:             dib->bits + dib->linesize * (dib->ysize - (xy[1] + y) - 1) +
218:                 xy[0] * dib->pixelsize,
219:             im->image[y],
220:             im->xsize
221:         );
222:     }
223: }
224: 
225: void
226: ImagingExposeDIB(ImagingDIB dib, void *dc) {
227:     /* Copy bitmap to display */
228: 
229:     if (dib->palette != 0) {
230:         SelectPalette((HDC)dc, dib->palette, FALSE);
231:     }
232:     BitBlt((HDC)dc, 0, 0, dib->xsize, dib->ysize, dib->dc, 0, 0, SRCCOPY);
233: }
234: 
235: void
236: ImagingDrawDIB(ImagingDIB dib, void *dc, int dst[4], int src[4]) {
237:     /* Copy bitmap to printer/display */
238: 
239:     if (GetDeviceCaps((HDC)dc, RASTERCAPS) & RC_STRETCHDIB) {
240:         /* stretchdib (printers) */
241:         StretchDIBits(
242:             (HDC)dc,
243:             dst[0],
244:             dst[1],
245:             dst[2] - dst[0],
246:             dst[3] - dst[1],
247:             src[0],
248:             src[1],
249:             src[2] - src[0],
250:             src[3] - src[1],
251:             dib->bits,
252:             dib->info,
253:             DIB_RGB_COLORS,
254:             SRCCOPY
255:         );
256:     } else {
257:         /* stretchblt (displays) */
258:         if (dib->palette != 0) {
259:             SelectPalette((HDC)dc, dib->palette, FALSE);
260:         }
261:         StretchBlt(
262:             (HDC)dc,
263:             dst[0],
264:             dst[1],
265:             dst[2] - dst[0],
266:             dst[3] - dst[1],
267:             dib->dc,
268:             src[0],
269:             src[1],
270:             src[2] - src[0],
271:             src[3] - src[1],
272:             SRCCOPY
273:         );
274:     }
275: }
276: 
277: int
278: ImagingQueryPaletteDIB(ImagingDIB dib, void *dc) {
279:     /* Install bitmap palette */
280: 
281:     int n;
282: 
283:     if (dib->palette != 0) {
284:         /* Realize associated palette */
285:         HPALETTE now = SelectPalette((HDC)dc, dib->palette, FALSE);
286:         n = RealizePalette((HDC)dc);
287: 
288:         /* Restore palette */
289:         SelectPalette((HDC)dc, now, FALSE);
290: 
291:     } else {
292:         n = 0;
293:     }
294: 
295:     return n; /* number of colours that was changed */
296: }
297: 
298: void
299: ImagingDeleteDIB(ImagingDIB dib) {
300:     /* Clean up */
301: 
302:     if (dib->palette) {
303:         DeleteObject(dib->palette);
304:     }
305:     if (dib->bitmap) {
306:         SelectObject(dib->dc, dib->old_bitmap);
307:         DeleteObject(dib->bitmap);
308:     }
309:     if (dib->dc) {
310:         DeleteDC(dib->dc);
311:     }
312:     free(dib->info);
313: }
314: 
315: #endif /* _WIN32 */

