1: /*
2:  * The Python Imaging Library.
3:  * $Id$
4:  *
5:  * TK interface for Python Imaging objects
6:  *
7:  * Copies (parts of) a named display memory to a photo image object.
8:  * Also contains code to create an display memory.  Under Tk, a
9:  * display memory is simply an "L" or "RGB" image memory that is
10:  * allocated in a single block.
11:  *
12:  * To use this module, import the _imagingtk module (ImageTk does
13:  * this for you).
14:  *
15:  * If you're using Python in an embedded context, you can add the
16:  * following lines to your Tcl_AppInit function (in tkappinit.c)
17:  * instead.  Put them after the calls to Tcl_Init and Tk_Init:
18:  *
19:  *      {
20:  *          extern void TkImaging_Init(Tcl_Interp* interp);
21:  *          TkImaging_Init(interp);
22:  *      }
23:  *
24:  * This registers a Tcl command called "PyImagingPhoto", which is used
25:  * to communicate between PIL and Tk's PhotoImage handler.
26:  *
27: 
28:  * History:
29:  * 1995-09-12 fl  Created
30:  * 1996-04-08 fl  Ready for release
31:  * 1997-05-09 fl  Use command instead of image type
32:  * 2001-03-18 fl  Initialize alpha layer pointer (struct changed in Tk 8.3)
33:  * 2003-04-23 fl  Fixed building for Tk 8.4.1 and later (Jack Jansen)
34:  * 2004-06-24 fl  Fixed building for Tk 8.4.6 and later.
35:  *
36:  * Copyright (c) 1997-2004 by Secret Labs AB
37:  * Copyright (c) 1995-2004 by Fredrik Lundh
38:  *
39:  * See the README file for information on usage and redistribution.
40:  */
41: 
42: #include "../libImaging/Imaging.h"
43: #include "_tkmini.h"
44: 
45: #include <stdlib.h>
46: 
47: /*
48:  * Global vars for Tcl / Tk functions.  We load these symbols from the tkinter
49:  * extension module or loaded Tcl / Tk libraries at run-time.
50:  */
51: static Tcl_CreateCommand_t TCL_CREATE_COMMAND;
52: static Tcl_AppendResult_t TCL_APPEND_RESULT;
53: static Tk_FindPhoto_t TK_FIND_PHOTO;
54: static Tk_PhotoGetImage_t TK_PHOTO_GET_IMAGE;
55: static Tk_PhotoPutBlock_t TK_PHOTO_PUT_BLOCK;
56: 
57: static Imaging
58: ImagingFind(const char *name) {
59:     PyObject *capsule;
60:     int direct_pointer = 0;
61:     const char *expected = "capsule object \"" IMAGING_MAGIC "\" at 0x";
62: 
63:     if (name[0] == '<') {
64:         name++;
65:     } else {
66:         // Special case for PyPy, where the string representation of a Capsule
67:         // refers directly to the pointer itself, not to the PyCapsule object.
68:         direct_pointer = 1;
69:     }
70: 
71:     if (strncmp(name, expected, strlen(expected))) {
72:         return NULL;
73:     }
74: 
75:     capsule = (PyObject *)strtoull(name + strlen(expected), NULL, 16);
76: 
77:     if (direct_pointer) {
78:         return (Imaging)capsule;
79:     }
80: 
81:     if (!PyCapsule_IsValid(capsule, IMAGING_MAGIC)) {
82:         PyErr_Format(PyExc_TypeError, "Expected '%s' Capsule", IMAGING_MAGIC);
83:         return NULL;
84:     }
85: 
86:     return (Imaging)PyCapsule_GetPointer(capsule, IMAGING_MAGIC);
87: }
88: 
89: static int
90: PyImagingPhotoPut(
91:     ClientData clientdata, Tcl_Interp *interp, int argc, const char **argv
92: ) {
93:     Imaging im;
94:     Tk_PhotoHandle photo;
95:     Tk_PhotoImageBlock block;
96: 
97:     if (argc != 3) {
98:         TCL_APPEND_RESULT(
99:             interp, "usage: ", argv[0], " destPhoto srcImage", (char *)NULL
100:         );
101:         return TCL_ERROR;
102:     }
103: 
104:     /* get Tcl PhotoImage handle */
105:     photo = TK_FIND_PHOTO(interp, argv[1]);
106:     if (photo == NULL) {
107:         TCL_APPEND_RESULT(interp, "destination photo must exist", (char *)NULL);
108:         return TCL_ERROR;
109:     }
110: 
111:     /* get PIL Image handle */
112:     im = ImagingFind(argv[2]);
113:     if (!im) {
114:         TCL_APPEND_RESULT(interp, "bad name", (char *)NULL);
115:         return TCL_ERROR;
116:     }
117:     if (!im->block) {
118:         TCL_APPEND_RESULT(interp, "bad display memory", (char *)NULL);
119:         return TCL_ERROR;
120:     }
121: 
122:     /* Mode */
123: 
124:     if (im->mode == IMAGING_MODE_1 || im->mode == IMAGING_MODE_L) {
125:         block.pixelSize = 1;
126:         block.offset[0] = block.offset[1] = block.offset[2] = block.offset[3] = 0;
127:     } else if (
128:         im->mode == IMAGING_MODE_RGB || im->mode == IMAGING_MODE_RGBA ||
129:         im->mode == IMAGING_MODE_RGBX || im->mode == IMAGING_MODE_RGBa
130:     ) {
131:         block.pixelSize = 4;
132:         block.offset[0] = 0;
133:         block.offset[1] = 1;
134:         block.offset[2] = 2;
135:         if (im->mode == IMAGING_MODE_RGBA) {
136:             block.offset[3] = 3; /* alpha (or reserved, under Tk 8.2) */
137:         } else {
138:             block.offset[3] = 0; /* no alpha */
139:         }
140:     } else {
141:         TCL_APPEND_RESULT(interp, "Bad mode", (char *)NULL);
142:         return TCL_ERROR;
143:     }
144: 
145:     block.width = im->xsize;
146:     block.height = im->ysize;
147:     block.pitch = im->linesize;
148:     block.pixelPtr = (unsigned char *)im->block;
149: 
150:     TK_PHOTO_PUT_BLOCK(
151:         interp, photo, &block, 0, 0, block.width, block.height, TK_PHOTO_COMPOSITE_SET
152:     );
153: 
154:     return TCL_OK;
155: }
156: 
157: static int
158: PyImagingPhotoGet(
159:     ClientData clientdata, Tcl_Interp *interp, int argc, const char **argv
160: ) {
161:     Imaging im;
162:     Tk_PhotoHandle photo;
163:     Tk_PhotoImageBlock block;
164:     int x, y, z;
165: 
166:     if (argc != 3) {
167:         TCL_APPEND_RESULT(
168:             interp, "usage: ", argv[0], " srcPhoto destImage", (char *)NULL
169:         );
170:         return TCL_ERROR;
171:     }
172: 
173:     /* get Tcl PhotoImage handle */
174:     photo = TK_FIND_PHOTO(interp, argv[1]);
175:     if (photo == NULL) {
176:         TCL_APPEND_RESULT(interp, "source photo must exist", (char *)NULL);
177:         return TCL_ERROR;
178:     }
179: 
180:     /* get PIL Image handle */
181:     im = ImagingFind(argv[2]);
182:     if (!im) {
183:         TCL_APPEND_RESULT(interp, "bad name", (char *)NULL);
184:         return TCL_ERROR;
185:     }
186: 
187:     TK_PHOTO_GET_IMAGE(photo, &block);
188: 
189:     for (y = 0; y < block.height; y++) {
