220: /*
221:  * Functions to fill global Tcl / Tk function pointers by dynamic loading
222:  */
223: 
224: #define TKINTER_FINDER "PIL._tkinter_finder"
225: 
226: #if defined(_WIN32) || defined(__WIN32__) || defined(WIN32) || defined(__CYGWIN__)
227: 
228: /*
229:  * On Windows, we can't load the tkinter module to get the Tcl or Tk symbols,
230:  * because Windows does not load symbols into the library name-space of
231:  * importing modules. So, knowing that tkinter has already been imported by
232:  * Python, we scan all modules in the running process for the Tcl and Tk
233:  * function names.
234:  */
235: #include <windows.h>
236: #define PSAPI_VERSION 1
237: #include <psapi.h>
238: /* Must be linked with 'psapi' library */
239: 
240: #define TKINTER_PKG "tkinter"
241: 
242: FARPROC
243: _dfunc(HMODULE lib_handle, const char *func_name) {
244:     /*
245:      * Load function `func_name` from `lib_handle`.
246:      * Set Python exception if we can't find `func_name` in `lib_handle`.
247:      * Returns function pointer or NULL if not present.
248:      */
249: 
250:     char message[100];
251: 
252:     FARPROC func = GetProcAddress(lib_handle, func_name);
253:     if (func == NULL) {
254:         sprintf(message, "Cannot load function %s", func_name);
255:         PyErr_SetString(PyExc_RuntimeError, message);
256:     }
257:     return func;
258: }
