260: int
261: get_tcl(HMODULE hMod) {
262:     /*
263:      * Try to fill Tcl global vars with function pointers. Return 0 for no
264:      * functions found, 1 for all functions found, -1 for some but not all
265:      * functions found.
266:      */
267: 
268:     if ((TCL_CREATE_COMMAND =
269:              (Tcl_CreateCommand_t)GetProcAddress(hMod, "Tcl_CreateCommand")) == NULL) {
270:         return 0; /* Maybe not Tcl module */
271:     }
272:     return ((TCL_APPEND_RESULT =
273:                  (Tcl_AppendResult_t)_dfunc(hMod, "Tcl_AppendResult")) == NULL)
274:                ? -1
275:                : 1;
276: }
277: 
278: int
279: get_tk(HMODULE hMod) {
280:     /*
281:      * Try to fill Tk global vars with function pointers. Return 0 for no
282:      * functions found, 1 for all functions found, -1 for some but not all
283:      * functions found.
284:      */
285: 
286:     FARPROC func = GetProcAddress(hMod, "Tk_PhotoPutBlock");
287:     if (func == NULL) { /* Maybe not Tk module */
288:         return 0;
289:     }
290:     if ((TK_PHOTO_GET_IMAGE = (Tk_PhotoGetImage_t)_dfunc(hMod, "Tk_PhotoGetImage")) ==
291:         NULL) {
292:         return -1;
293:     };
294:     if ((TK_FIND_PHOTO = (Tk_FindPhoto_t)_dfunc(hMod, "Tk_FindPhoto")) == NULL) {
295:         return -1;
296:     };
297:     TK_PHOTO_PUT_BLOCK = (Tk_PhotoPutBlock_t)func;
298:     return 1;
299: }
