301: int
302: load_tkinter_funcs(void) {
303:     /*
304:      * Load Tcl and Tk functions by searching all modules in current process.
305:      * Return 0 for success, non-zero for failure.
306:      */
307: 
308:     HMODULE *hMods = NULL;
309:     HANDLE hProcess;
310:     DWORD cbNeeded;
311:     unsigned int i;
312:     int found_tcl = 0;
313:     int found_tk = 0;
314: 
315:     /* First load tkinter module to make sure libraries are loaded */
316:     PyObject *pModule = PyImport_ImportModule(TKINTER_PKG);
317:     if (pModule == NULL) {
318:         return 1;
319:     }
320:     Py_DECREF(pModule);
321: 
322:     /* Returns pseudo-handle that does not need to be closed */
323:     hProcess = GetCurrentProcess();
324: 
325:     /* Allocate module handlers array */
326:     if (!EnumProcessModules(hProcess, NULL, 0, &cbNeeded)) {
327: #if defined(__CYGWIN__)
328:         PyErr_SetString(PyExc_OSError, "Call to EnumProcessModules failed");
329: #else
330:         PyErr_SetFromWindowsErr(0);
331: #endif
332:         return 1;
333:     }
334:     if (!(hMods = (HMODULE *)malloc(cbNeeded))) {
335:         PyErr_NoMemory();
336:         return 1;
337:     }
338: 
339:     /* Iterate through modules in this process looking for Tcl / Tk names */
340:     if (EnumProcessModules(hProcess, hMods, cbNeeded, &cbNeeded)) {
341:         for (i = 0; i < (cbNeeded / sizeof(HMODULE)); i++) {
342:             if (!found_tcl) {
343:                 found_tcl = get_tcl(hMods[i]);
344:                 if (found_tcl == -1) {
345:                     break;
346:                 }
347:             }
348:             if (!found_tk) {
349:                 found_tk = get_tk(hMods[i]);
350:                 if (found_tk == -1) {
351:                     break;
352:                 }
353:             }
354:             if (found_tcl && found_tk) {
355:                 break;
356:             }
357:         }
358:     }
359: 
360:     free(hMods);
361:     if (found_tcl == 0) {
362:         PyErr_SetString(PyExc_RuntimeError, "Could not find Tcl routines");
363:     } else if (found_tk == 0) {
364:         PyErr_SetString(PyExc_RuntimeError, "Could not find Tk routines");
365:     }
366:     return (int)((found_tcl != 1) || (found_tk != 1));
367: }
368: 
369: #else /* not Windows */
370: 
371: /*
372:  * On Unix, we can get the Tcl and Tk symbols from the tkinter module, because
373:  * tkinter uses these symbols, and the symbols are therefore visible in the
374:  * tkinter dynamic library (module).
375:  */
376: 
377: #include <dlfcn.h>
378: 
379: void *
380: _dfunc(void *lib_handle, const char *func_name) {
381:     /*
382:      * Load function `func_name` from `lib_handle`.
383:      * Set Python exception if we can't find `func_name` in `lib_handle`.
384:      * Returns function pointer or NULL if not present.
385:      */
386: 
387:     void *func;
388:     /* Reset errors. */
389:     dlerror();
390:     func = dlsym(lib_handle, func_name);
391:     if (func == NULL) {
392:         const char *error = dlerror();
393:         PyErr_SetString(PyExc_RuntimeError, error);
394:     }
395:     return func;
396: }
397: 
398: int
399: _func_loader(void *lib) {
400:     /*
401:      * Fill global function pointers from dynamic lib.
402:      * Return 1 if any pointer is NULL, 0 otherwise.
403:      */
404: 
405:     if ((TCL_CREATE_COMMAND = (Tcl_CreateCommand_t)_dfunc(lib, "Tcl_CreateCommand")) ==
406:         NULL) {
407:         return 1;
408:     }
409:     if ((TCL_APPEND_RESULT = (Tcl_AppendResult_t)_dfunc(lib, "Tcl_AppendResult")) ==
410:         NULL) {
411:         return 1;
412:     }
413:     if ((TK_PHOTO_GET_IMAGE = (Tk_PhotoGetImage_t)_dfunc(lib, "Tk_PhotoGetImage")) ==
414:         NULL) {
415:         return 1;
416:     }
417:     if ((TK_FIND_PHOTO = (Tk_FindPhoto_t)_dfunc(lib, "Tk_FindPhoto")) == NULL) {
418:         return 1;
419:     }
420:     return (
421:         (TK_PHOTO_PUT_BLOCK = (Tk_PhotoPutBlock_t)_dfunc(lib, "Tk_PhotoPutBlock")) ==
422:         NULL
423:     );
424: }
