426: int
427: load_tkinter_funcs(void) {
428:     /*
429:      * Load tkinter global funcs from tkinter compiled module.
430:      * Return 0 for success, non-zero for failure.
431:      */
432: 
433:     int ret = -1;
434:     void *main_program, *tkinter_lib;
435:     char *tkinter_libname;
436:     PyObject *pModule = NULL, *pString = NULL, *pBytes = NULL;
437: 
438:     /* Try loading from the main program namespace first */
439:     main_program = dlopen(NULL, RTLD_LAZY);
440:     if (_func_loader(main_program) == 0) {
441:         dlclose(main_program);
442:         return 0;
443:     }
444:     /* Clear exception triggered when we didn't find symbols above */
445:     PyErr_Clear();
446: 
447:     /* Now try finding the tkinter compiled module */
448:     pModule = PyImport_ImportModule(TKINTER_FINDER);
449:     if (pModule == NULL) {
450:         goto exit;
451:     }
452:     pString = PyObject_GetAttrString(pModule, "TKINTER_LIB");
453:     if (pString == NULL) {
454:         goto exit;
455:     }
456:     /* From module __file__ attribute to char *string for dlopen. */
457:     pBytes = PyUnicode_EncodeFSDefault(pString);
458:     if (pBytes == NULL) {
459:         goto exit;
460:     }
461:     tkinter_libname = PyBytes_AsString(pBytes);
462:     if (tkinter_libname == NULL) {
463:         goto exit;
464:     }
465:     tkinter_lib = dlopen(tkinter_libname, RTLD_LAZY);
466:     if (tkinter_lib == NULL) {
467:         PyErr_SetString(PyExc_RuntimeError, "Cannot dlopen tkinter module file");
468:         goto exit;
469:     }
470:     ret = _func_loader(tkinter_lib);
471:     /* dlclose probably safe because tkinter has been imported. */
472:     dlclose(tkinter_lib);
473: exit:
474:     dlclose(main_program);
475:     Py_XDECREF(pModule);
476:     Py_XDECREF(pString);
477:     Py_XDECREF(pBytes);
478:     return ret;
479: }
480: #endif /* end not Windows */

